import{c as s,Q as n,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E7%9F%A2%E9%87%8F%E7%AE%97%E5%AD%90%E6%A0%B8%E5%87%BD%E6%95%B0%E5%AE%9E%E7%8E%B0%E6%B5%81%E7%A8%8B.B8sODiHu.png",p="/assets/%E7%AE%97%E5%AD%90%E8%AE%A1%E7%AE%97%E9%80%BB%E8%BE%91.C5A3tf7w.png",o="/assets/Add%E7%AE%97%E5%AD%90%E5%AE%9E%E7%8E%B0%E6%B5%81%E7%A8%8B.DrKDKlbT.png",b=JSON.parse('{"title":"基础矢量算子","description":"","frontmatter":{},"headers":[{"level":1,"title":"基础矢量算子","slug":"基础矢量算子"},{"level":2,"title":"算子分析","slug":"算子分析"},{"level":2,"title":"核函数定义","slug":"核函数定义"},{"level":2,"title":"算子类实现","slug":"算子类实现"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矢量编程/基础矢量算子.md","filePath":"guide/算子实践参考/SIMD算子实现/矢量编程/基础矢量算子.md"}'),i={name:"guide/算子实践参考/SIMD算子实现/矢量编程/基础矢量算子.md"};function c(r,a,d,u,g,h){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="基础矢量算子" tabindex="-1">基础矢量算子 <a class="header-anchor" href="#基础矢量算子" aria-label="Permalink to &quot;基础矢量算子&quot;">​</a></h1><p>基于Ascend C方式实现基础矢量算子核函数的流程如下图所示。</p><p><strong>图 1</strong> 矢量算子核函数实现流程<br><img src="'+l+'" alt="" title="矢量算子核函数实现流程"></p><ul><li>算子分析：分析算子的数学表达式、输入、输出以及计算逻辑的实现，明确需要调用的Ascend C接口。</li><li>核函数定义：定义Ascend C算子入口函数。</li><li>根据<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/SIMD编程/基于TPipe和TQue编程.html#section116515238815">矢量编程范式</a>实现算子类：完成核函数的内部实现，包括3个基本任务：CopyIn，Compute，CopyOut。</li></ul><p>下文以输入为half数据类型且shape的最后一维为32Bytes对齐、在单核上运行的、一次完成计算的Add算子为例，对上述步骤进行详细介绍。</p><h2 id="算子分析" tabindex="-1">算子分析 <a class="header-anchor" href="#算子分析" aria-label="Permalink to &quot;算子分析&quot;">​</a></h2><p>算子分析具体步骤如下：</p><ol><li><p>明确算子的数学表达式及计算逻辑。</p><p>Add算子的数学表达式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = x + y</span></span></code></pre></div><p>计算逻辑是：Ascend C提供的<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">矢量计算接口</a>的操作元素都为<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/LocalTensor.md" target="_blank" rel="noreferrer">LocalTensor</a>，输入数据需要先从外部存储（Global Memory）搬运进片上存储（Unified Buffer），然后使用计算接口完成两个输入参数相加，得到最终结果，再搬出到外部存储上。Ascend C Add算子的计算逻辑如下图所示。</p><p><strong>图 2</strong> 算子计算逻辑<br><img src="'+p+`" alt="" title="算子计算逻辑"></p></li><li><p>明确输入和输出。</p><ul><li>Add算子有两个输入：x与y；输出为z。</li><li>本样例中算子的输入支持的数据类型为half（float16），算子输出的数据类型与输入的数据类型相同。</li><li>算子输入支持的shape为（1，2048），输出shape与输入shape相同。</li><li>算子输入支持的<a href="./../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.html">format</a>为：ND。</li></ul></li><li><p>确定核函数名称和参数。</p><ul><li>您可以自定义核函数名称，本样例中核函数命名为vec_add_custom。</li><li>根据对算子输入输出的分析，确定核函数有3个参数x，y，z；x，y为输入在Global Memory上的内存地址，z为输出在Global Memory上的内存地址。</li></ul></li><li><p>确定算子实现所需接口。</p><ul><li>实现涉及外部存储和内部存储间的数据搬运，查看Ascend C API参考中的数据搬运接口，需要使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>来实现数据搬运。</li><li>本样例只涉及矢量计算的加法操作，查看Ascend C API参考中的<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Memory%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97.md" target="_blank" rel="noreferrer">矢量计算</a>接口，初步分析可使用基础算术Add接口<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">Add</a>实现x+y。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TQue%E7%AE%80%E4%BB%8B.md" target="_blank" rel="noreferrer">Queue队列</a>管理计算中使用的Tensor数据结构，具体使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>等接口。</li></ul></li></ol><p>通过以上分析，得到Ascend C Add算子的设计规格如下：</p><ul><li><p>算子类型（OpType）：Add</p></li><li><p>算子输入输出：</p><p><strong>表 1</strong> Add算子输入输出规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;name&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;shape&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;data type&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;format&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;x（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;y（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;z（输出）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>核函数名称：vec_add_custom</p></li><li><p>使用的主要接口：</p><ul><li>DataCopy：数据搬移接口</li><li>Add：矢量基础算术接口</li><li>EnQue、DeQue等接口：Queue队列管理接口</li></ul></li><li><p>算子实现文件名称：vector_add.asc</p></li></ul><h2 id="核函数定义" tabindex="-1">核函数定义 <a class="header-anchor" href="#核函数定义" aria-label="Permalink to &quot;核函数定义&quot;">​</a></h2><p>根据<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html">核函数</a>中介绍的规则进行核函数的定义。</p><ol><li><p>函数原型定义</p><p>本样例中，函数名为vector_add_custom（核函数名称可自定义），根据<a href="#zh-cn_topic_0000002201157438_section4870456573">算子分析</a>中对算子输入输出的分析，确定有3个参数x，y，z，其中x，y为输入内存，z为输出内存。根据<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html#zh-cn_topic_0000001447989210_section1915102519220">核函数</a>的规则介绍，函数原型定义如下所示：使用__global__函数类型限定符标识它是一个核函数，可以被&lt;&lt;&lt;&gt;&gt;&gt;调用；使用__vector__函数类型限定符标识该核函数在设备端aicore的Vector Core上执行；为方便起见，统一使用GM_ADDR宏修饰入参，GM_ADDR宏定义请参考<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html#zh-cn_topic_0000001447989210_li94421027152419">核函数</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __vector__ void vector_add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>调用算子类的Init和Process函数。</p><p>算子类的Init函数，完成内存初始化相关工作，Process函数完成算子实现的核心逻辑，具体介绍参见<a href="#zh-cn_topic_0000002201157438_section10423482111">算子类实现</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __vector__ void vector_add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::TPipe pipe;</span></span>
<span class="line"><span>    KernelAdd op;</span></span>
<span class="line"><span>    op.Init(x, y, z, &amp;pipe);</span></span>
<span class="line"><span>    op.Process();</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>根据<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html#zh-cn_topic_0000001447989210_section1915102519220">核函数定义和调用</a>章节，调用核函数时，除了需要传入参数x，y，z，还需要传入numBlocks（核函数执行的核数），nullptr（保留参数，设置为nullptr），stream（应用程序中维护异步操作执行顺序的stream）来规定核函数的执行配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vector_add_custom&lt;&lt;&lt;numBlocks, nullptr, stream&gt;&gt;&gt;(xDevice, yDevice, zDevice);</span></span></code></pre></div></li></ol><h2 id="算子类实现" tabindex="-1">算子类实现 <a class="header-anchor" href="#算子类实现" aria-label="Permalink to &quot;算子类实现&quot;">​</a></h2><p>根据上一节介绍，核函数中会调用算子类的Init和Process函数，本节具体讲解如何基于编程范式实现算子类。</p><p>根据矢量编程范式对Add算子的实现流程进行设计的思路如下，矢量编程范式请参考<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/SIMD编程/基于TPipe和TQue编程.html#section116515238815">矢量编程范式</a>，设计完成后得到的Add算子实现流程图参见<a href="#zh-cn_topic_0000002201157438_fig4134406304">图3 Add算子实现流程</a>：</p><ul><li>Add算子的实现流程分为3个基本任务：CopyIn，Compute，CopyOut。CopyIn任务负责将Global Memory上的输入Tensor xGm和yGm搬运至Local Memory，分别存储在xLocal，yLocal，Compute任务负责对xLocal，yLocal执行加法操作，计算结果存储在zLocal中，CopyOut任务负责将输出数据从zLocal搬运至Global Memory上的输出Tensor zGm中。</li><li>CopyIn，Compute任务间通过VECIN队列inQueueX，inQueueY进行同步，Compute，CopyOut任务间通过VECOUT队列outQueueZ进行同步。</li><li>任务间交互使用到的内存、临时变量的内存统一使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TPipe.md" target="_blank" rel="noreferrer">Pipe内存管理对象</a>进行管理。</li></ul><p><strong>图 3</strong> Add算子实现流程<br><img src="`+o+`" alt="" title="Add算子实现流程"></p><p>算子类中主要实现上述流程，包含对外开放的初始化Init函数和核心处理函数Process，Process函数中会对上图中的三个基本任务进行调用；同时包括一些算子实现中会用到的私有成员，比如上图中的GlobalTensor（xGm、yGm、zGm）和VECIN、VECOUT队列等。KernelAdd算子类具体成员如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class KernelAdd {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline KernelAdd() {}</span></span>
<span class="line"><span>    // 初始化函数，完成内存初始化相关操作</span></span>
<span class="line"><span>    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, AscendC::TPipe* pipeIn){}</span></span>
<span class="line"><span>    // 核心处理函数，实现算子逻辑，调用私有成员函数CopyIn、Compute、CopyOut完成矢量算子的三级流水操作</span></span>
<span class="line"><span>    __aicore__ inline void Process(){}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    // 搬入函数，完成CopyIn阶段的处理，被核心Process函数调用</span></span>
<span class="line"><span>    __aicore__ inline void CopyIn(){}</span></span>
<span class="line"><span>    // 计算函数，完成Compute阶段的处理，被核心Process函数调用</span></span>
<span class="line"><span>    __aicore__ inline void Compute(){}</span></span>
<span class="line"><span>    // 搬出函数，完成CopyOut阶段的处理，被核心Process函数调用</span></span>
<span class="line"><span>    __aicore__ inline void CopyOut(){}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    AscendC::TPipe* pipe;  // Pipe内存管理对象</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECIN, 1&gt; inQueueX;  // 输入数据Queue队列管理对象，TPosition为VECIN</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECIN, 1&gt; inQueueY;  // 输入数据Queue队列管理对象，TPosition为VECIN</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECOUT, 1&gt; outQueueZ;  // 输出数据Queue队列管理对象，TPosition为VECOUT</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;half&gt; xGm;  // 管理输入输出Global Memory内存地址的对象，其中xGm, yGm为输入，zGm为输出</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;half&gt; yGm;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;half&gt; zGm;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>初始化函数主要完成以下内容：</p><ul><li><p>设置输入输出Global Tensor的Global Memory内存地址。</p><p>本样例中的分配方案是：数据整体长度TOTAL_LENGTH为1 * 2048，使用GlobalTensor类的<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetGlobalBuffer.md" target="_blank" rel="noreferrer">SetGlobalBuffer</a>接口设定该核上Global Memory的起始地址以及长度。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xGm.SetGlobalBuffer((__gm__ half *)x, TOTAL_LENGTH);</span></span></code></pre></div></li><li><p>通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TPipe.md" target="_blank" rel="noreferrer">Pipe内存管理对象</a>为输入输出Queue分配内存。</p><p>比如，为输入x的Queue分配内存，可以通过如下代码段实现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pipe-&gt;InitBuffer(inQueueX, 1, TOTAL_LENGTH * sizeof(half))</span></span></code></pre></div></li></ul><p>具体的初始化函数代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr int32_t TOTAL_LENGTH = 1 * 2048;  // 数据总长</span></span>
<span class="line"><span>__aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, AscendC::TPipe* pipeIn)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    pipe = pipeIn;    </span></span>
<span class="line"><span>    // 设置Global Memory的起始地址以及长度</span></span>
<span class="line"><span>    xGm.SetGlobalBuffer((__gm__ half*)x, TOTAL_LENGTH);</span></span>
<span class="line"><span>    yGm.SetGlobalBuffer((__gm__ half*)y, TOTAL_LENGTH);</span></span>
<span class="line"><span>    zGm.SetGlobalBuffer((__gm__ half*)z, TOTAL_LENGTH);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 通过Pipe内存管理对象为输入输出Queue分配内存</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(inQueueX, 1, TOTAL_LENGTH * sizeof(half));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(inQueueY, 1, TOTAL_LENGTH * sizeof(half));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(outQueueZ, 1, TOTAL_LENGTH * sizeof(half));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>基于矢量编程范式，将核函数的实现分为3个基本任务：CopyIn，Compute，CopyOut。Process函数中通过如下方式调用这三个函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Process()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    CopyIn();</span></span>
<span class="line"><span>    Compute();</span></span>
<span class="line"><span>    CopyOut();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>根据编程范式上面的算法分析，将整个计算拆分成三个Stage，用户单独编写每个Stage的代码，三阶段流程示意图参见<a href="#zh-cn_topic_0000002201157438_fig4134406304">图3</a>，具体流程如下：</p><ol><li><p>Stage1：CopyIn函数实现。</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>接口将GlobalTensor数据拷贝到LocalTensor。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>将LocalTensor放入VECIN的Queue中。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void CopyIn()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // 从Que中为LocalTensor分配内存</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;half&gt; xLocal = inQueueX.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;half&gt; yLocal = inQueueY.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>    // 将GlobalTensor数据拷贝到LocalTensor</span></span>
<span class="line"><span>    AscendC::DataCopy(xLocal, xGm, TOTAL_LENGTH);</span></span>
<span class="line"><span>    AscendC::DataCopy(yLocal, yGm, TOTAL_LENGTH);</span></span>
<span class="line"><span>    // LocalTensor放入VECIN的Queue中</span></span>
<span class="line"><span>    inQueueX.EnQue(xLocal);</span></span>
<span class="line"><span>    inQueueY.EnQue(yLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Stage2：Compute函数实现。</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>从VECIN中取出LocalTensor。</li><li>使用Ascend C接口<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">Add</a>完成矢量计算。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>将计算结果LocalTensor放入到VECOUT的Queue中。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>释放不再使用的LocalTensor。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Compute()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // 将Input从VECIN的Queue中取出</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;half&gt; xLocal = inQueueX.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;half&gt; yLocal = inQueueY.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;half&gt; zLocal = outQueueZ.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>    // 调用Add算子进行计算</span></span>
<span class="line"><span>    AscendC::Add(zLocal, xLocal, yLocal, TOTAL_LENGTH);</span></span>
<span class="line"><span>    // 将计算结果LocalTensor放入到VECOUT的Queue中</span></span>
<span class="line"><span>    outQueueZ.EnQue&lt;half&gt;(zLocal);</span></span>
<span class="line"><span>    // 释放LocalTensor</span></span>
<span class="line"><span>    inQueueX.FreeTensor(xLocal);</span></span>
<span class="line"><span>    inQueueY.FreeTensor(yLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Stage3：CopyOut函数实现。</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>接口从VECOUT的Queue中取出LocalTensor。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>接口将LocalTensor拷贝到GlobalTensor上。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>将不再使用的LocalTensor进行回收。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __aicore__ inline void CopyOut()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // 将计算结果从VECOUT的Queue中取出</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;half&gt; zLocal = outQueueZ.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>    // 将计算结果从LocalTensor数据拷贝到GlobalTensor</span></span>
<span class="line"><span>    AscendC::DataCopy(zGm, zLocal, TOTAL_LENGTH);</span></span>
<span class="line"><span>    // 释放LocalTensor</span></span>
<span class="line"><span>    outQueueZ.FreeTensor(zLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol>`,28)])])}const m=s(i,[["render",c]]);export{b as __pageData,m as default};
